{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-b4GHCY/src/address.js","content":"/**
 * Cell addresses: one or two letters naming a column (A..Z, AA..ZZ) and one
 * to three digits naming a row (>= 1).
 */

const ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Bijective base-26: A=1 ... Z=26, AA=27 ... ZZ=702. */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters.toUpperCase()) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

export function numToCol(n) {
  let s = ''
  let v = n
  while (v > 0) {
    v -= 1
    s = String.fromCharCode(65 + (v % 26)) + s
    v = Math.floor(v / 26)
  }
  return s
}

/**
 * Parse a word (as it appears in a formula or as the address column of a
 * sheet line, upper-cased) into an address descriptor. Returns
 * { valid: false } when the word is not an address inside the addressable
 * range.
 */
export function parseAddress(word) {
  const m = ADDR_RE.exec(word)
  if (!m) return { valid: false }
  const row = parseInt(m[2], 10)
  if (row < 1) return { valid: false }
  const letters = m[1].toUpperCase()
  const col = colToNum(letters)
  return { valid: true, col, row, canonical: `${letters}${row}` }
}

export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

