{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-b4GHCY/src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text following the leading `=`).
 */

export class LexError extends Error {}

const TOKEN_SPECS = [
  ['WS', /^[ \t]+/],
  ['NUM', /^[0-9]+(\.[0-9]+)?/],
  ['IDENT', /^[A-Za-z]+[0-9]*/],
  ['LE', /^<=/],
  ['GE', /^>=/],
  ['NE', /^<>/],
  ['LT', /^</],
  ['GT', /^>/],
  ['EQ', /^=/],
  ['CARET', /^\^/],
  ['STAR', /^\*/],
  ['SLASH', /^\//],
  ['PLUS', /^\+/],
  ['MINUS', /^-/],
  ['LP', /^\(/],
  ['RP', /^\)/],
  ['COMMA', /^,/],
  ['COLON', /^:/],
]

export function lex(text) {
  const tokens = []
  let pos = 0
  while (pos < text.length) {
    const slice = text.slice(pos)
    let matched = false
    for (const [type, re] of TOKEN_SPECS) {
      const m = re.exec(slice)
      if (m) {
        matched = true
        if (type !== 'WS') {
          tokens.push({ type, value: m[0], pos })
        }
        pos += m[0].length
        break
      }
    }
    if (!matched) {
      throw new LexError(`unexpected character at ${pos}`)
    }
  }
  return tokens
}
"}

