export class ParseError extends Error {}

const COMPARE_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const OP_TEXT = {
  EQ: '=',
  NE: '<>',
  LT: '<',
  LE: '<=',
  GT: '>',
  GE: '>=',
}

/**
 * Parse a formula body (text after the leading `=`) into an AST. Throws
 * ParseError when the grammar rejects the text.
 */
export function parseFormula(text) {
  let tokens
  try {
    tokens = lex(text)
  } catch (e) {
    if (e instanceof LexError) throw new ParseError(e.message)
    throw e
  }
  let pos = 0

  function peek() {
    return tokens[pos]
  }
  function at(offset) {
    return tokens[pos + offset]
  }
  function advance() {
    return tokens[pos++]
  }
  function expect(type) {
    const t = peek()
    if (!t || t.type !== type) {
      throw new ParseError(`expected ${type}`)
    }
    return advance()
  }

  function parseComparison() {
    let left = parseAdditive()
    while (peek() && COMPARE_OPS.has(peek().type)) {
      const op = advance()
      const right = parseAdditive()
      left = { type: 'binop', op: OP_TEXT[op.type], left, right }
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    while (peek() && (peek().type === 'PLUS' || peek().type === 'MINUS')) {
      const op = advance()
      const right = parseMultiplicative()
      left = { type: 'binop', op: op.type === 'PLUS' ? '+' : '-', left, right }
    }
    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    while (peek() && (peek().type === 'STAR' || peek().type === 'SLASH')) {
      const op = advance()
      const right = parsePower()
      left = { type: 'binop', op: op.type === 'STAR' ? '*' : '/', left, right }
    }
    return left
  }

  function parsePower() {
    const base = parseSignedPrimary()
    if (peek() && peek().type === 'CARET') {
      advance()
      const right = parsePower()
      return { type: 'binop', op: '^', left: base, right }
    }
    return base
  }

  function parseSignedPrimary() {
    if (peek() && (peek().type === 'PLUS' || peek().type === 'MINUS')) {
      const op = advance()
      const expr = parseSignedPrimary()
      return { type: 'unary', op: op.type === 'PLUS' ? '+' : '-', expr }
    }
    return parsePrimary()
  }

  function parseArg() {
    // A range is accepted only directly as a function argument: IDENT ':' IDENT
    const t0 = peek()
    if (
      t0 &&
      t0.type === 'IDENT' &&
      at(1) &&
      at(1).type === 'COLON' &&
      at(2) &&
      at(2).type === 'IDENT'
    ) {
      const after = at(3)
      if (!after || after.type === 'COMMA' || after.type === 'RP') {
        advance() // IDENT
        advance() // COLON
        const toTok = advance() // IDENT
        return { type: 'range', from: t0.value.toUpperCase(), to: toTok.value.toUpperCase() }
      }
    }
    return parseComparison()
  }

  function parsePrimary() {
    const t = peek()
    if (!t) throw new ParseError('unexpected end of formula')
    if (t.type === 'NUM') {
      advance()
      return { type: 'num', value: parseFloat(t.value) }
    }
    if (t.type === 'LP') {
      advance()
      const expr = parseComparison()
      expect('RP')
      return expr
    }
    if (t.type === 'IDENT') {
      advance()
      if (peek() && peek().type === 'LP') {
        advance()
        const args = []
        if (peek() && peek().type !== 'RP') {
          args.push(parseArg())
          while (peek() && peek().type === 'COMMA') {
            advance()
            args.push(parseArg())
          }
        }
        expect('RP')
        return { type: 'call', name: t.value.toUpperCase(), args }
      }
      const upper = t.value.toUpperCase()
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'addr', text: upper }
    }
    throw new ParseError(`unexpected token ${t.type}`)
  }

  const result = parseComparison()
  if (pos !== tokens.length) {
    throw new ParseError('trailing input')
  }
  return result
}
"}

