/**
 * Parse the raw text of a sheet into an ordered Map from canonical address
 * to { content, col, row }.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let idx = 0
    while (idx < stripped.length && stripped[idx] !== ' ' && stripped[idx] !== '\t') idx++
    const addrRaw = stripped.slice(0, idx)
    let rest = stripped.slice(idx)
    let j = 0
    while (j < rest.length && (rest[j] === ' ' || rest[j] === '\t')) j++
    const content = rest.slice(j)

    const upper = addrRaw.toUpperCase()
    const addr = parseAddress(upper)
    if (!addr.valid) {
      throw new SheetError(lineNo, `invalid cell address ${upper}`)
    }
    if (cells.has(addr.canonical)) {
      throw new SheetError(lineNo, `cell ${addr.canonical} is declared twice`)
    }
    cells.set(addr.canonical, { content, col: addr.col, row: addr.row })
  }

  return cells
}

export function sortedAddresses(cells) {
  return [...cells.keys()].sort((a, b) => {
    const ca = cells.get(a)
    const cb = cells.get(b)
    if (ca.col !== cb.col) return ca.col - cb.col
    return ca.row - cb.row
  })
}
