/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { parseSheet, sortedAddresses, SheetError } from './sheet.js'
import { makeEvaluator } from './evaluate.js'
import { formatValue } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }
  const mode = argv[0]

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const evaluator = makeEvaluator(cells)
  const addrs = sortedAddresses(cells)
  const out = []

  if (mode === 'values') {
    for (const addr of addrs) {
      const v = evaluator.evaluateCell(addr)
      out.push(`${addr}=${formatValue(v)}`)
    }
  } else {
    for (const addr of addrs) {
      const deps = evaluator.depsOf(addr)
      out.push(`${addr}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }

  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  process.exit(0)
}

